    static Map<?,?> latest(Path root)throws IOException{var value=object(json(root.resolve("latest.json"),1048576));keys(value,"attempt","status");String id=text(value.get("attempt"));if(!id.matches("[0-9]{6}"))throw new IOException("Invalid Hi-C latest attempt ID");String newest="";try(var stream=Files.list(directory(root.resolve("attempts")))){for(Path p:stream.toList()){directory(p);String name=p.getFileName().toString();if(!name.matches("[0-9]{6}"))throw new IOException("Unexpected Hi-C attempt entry");if(name.compareTo(newest)>0)newest=name;}}if(!id.equals(newest))throw new IOException("Latest Hi-C pointer omits a newer retained attempt; no fallback to earlier success");return value;}
